--     DELETE FROM product_photos WHERE sku IN (SELECT sku FROM products WHERE supplier_id = 'shop-hookahs');
--     DELETE FROM favourites WHERE sku IN (SELECT sku FROM products WHERE supplier_id = 'shop-hookahs');
--     DELETE FROM stock_alerts WHERE sku IN (SELECT sku FROM products WHERE supplier_id = 'shop-hookahs');
--     DELETE FROM stock_moves WHERE sku IN (SELECT sku FROM products WHERE supplier_id = 'shop-hookahs');
--     DELETE FROM products WHERE supplier_id = 'shop-hookahs' AND sku LIKE 'OSS-14____';
--     DELETE FROM catalog_imports WHERE supplier_id = 'shop-hookahs'; DELETE FROM suppliers WHERE id = 'shop-hookahs';
